/// almide-kernel embedded as an inlinable `mod almide_kernel`, dropped into the
/// runtime source wherever the `matrix` module is used (see emit_runtime_crate).
pub const ALMIDE_KERNEL_INLINE: &str = "#[allow(dead_code, unused_imports, unused_variables, unused_parens, unused_mut, non_snake_case, clippy::all)]\nmod almide_kernel {\npub mod matmul {\n//! Dense matmul `C = A·B` (m×k · k×n, row-major). SIMD inner product: transpose\n//! B once so each column becomes a contiguous row, then a SIMD dot per (i,j).\n//!\n//! This beats Almide's tiled-*scalar* mul by vectorizing the inner product. BLAS\n//! lives here too — register-tiled micro-kernels (6x16, packing, prefetch) are\n//! the ceiling and we don't reach it; this is the SIMD-dot rung, enough to pass\n//! a scalar inner loop. Used for sdpa's QKᵀ and weights·V.\n\n/// Row-major shape of the product `C(m×n) = A(m×k)·B(k×n)`. Bundles the three\n/// extents so the x86 kernel's edge pass stays inside the parameter budget.\n#[cfg(target_arch = \"x86_64\")]\n#[derive(Clone, Copy)]\nstruct Dims {\n    m: usize,\n    k: usize,\n    n: usize,\n}\n\n/// Naive tiled-scalar reference (≈ Almide's mul).\npub fn matmul_naive(a: &[f64], m: usize, k: usize, b: &[f64], n: usize, out: &mut [f64]) {\n    out.fill(0.0);\n    const T: usize = 32;\n    for i0 in (0..m).step_by(T) {\n        for k0 in (0..k).step_by(T) {\n            for j0 in (0..n).step_by(T) {\n                let tile = Tile {\n                    rows: i0..(i0 + T).min(m),\n                    depth: k0..(k0 + T).min(k),\n                    cols: j0..(j0 + T).min(n),\n                };\n                accumulate_tile(a, k, b, n, out, &tile);\n            }\n        }\n    }\n}\n\n/// One cache tile of the tiled reference: the (rows × depth × cols) index box\n/// the three outer loops carved out.\nstruct Tile {\n    rows: std::ops::Range<usize>,\n    depth: std::ops::Range<usize>,\n    cols: std::ops::Range<usize>,\n}\n\n/// `C[tile.rows, tile.cols] += A[tile.rows, tile.depth] · B[tile.depth, tile.cols]`.\n///\n/// The column span is taken as a slice pair so the innermost loop walks two\n/// contiguous rows — same operation order as the index form it replaced, so the\n/// result stays bit-identical to what the Wyve proof pins.\nfn accumulate_tile(a: &[f64], k: usize, b: &[f64], n: usize, out: &mut [f64], tile: &Tile) {\n    let (c0, c1) = (tile.cols.start, tile.cols.end);\n    for i in tile.rows.clone() {\n        for kk in tile.depth.clone() {\n            let aik = a[i * k + kk];\n            let orow = &mut out[i * n + c0..i * n + c1];\n            let brow = &b[kk * n + c0..kk * n + c1];\n            for (o, bv) in orow.iter_mut().zip(brow) {\n                *o += aik * bv;\n            }\n        }\n    }\n}\n\n#[cfg(target_arch = \"x86_64\")]\n#[target_feature(enable = \"avx2,fma\")]\n#[allow(dead_code)]\nunsafe fn matmul_avx(a: &[f64], m: usize, k: usize, b: &[f64], n: usize, out: &mut [f64]) {\n    use std::arch::x86_64::*;\n    // transpose B → bt (n×k), columns become contiguous rows\n    let mut bt = vec![0.0f64; n * k];\n    for kk in 0..k {\n        let brow = &b[kk * n..kk * n + n];\n        for j in 0..n {\n            bt[j * k + kk] = brow[j];\n        }\n    }\n    let chunks = k / 4;\n    for i in 0..m {\n        let ai = &a[i * k..i * k + k];\n        for j in 0..n {\n            let bj = &bt[j * k..j * k + k];\n            let mut acc = _mm256_setzero_pd();\n            for c in 0..chunks {\n                let av = _mm256_loadu_pd(ai.as_ptr().add(c * 4));\n                let bv = _mm256_loadu_pd(bj.as_ptr().add(c * 4));\n                acc = _mm256_fmadd_pd(av, bv, acc);\n            }\n            let hi = _mm256_extractf128_pd(acc, 1);\n            let lo = _mm256_castpd256_pd128(acc);\n            let s = _mm_add_pd(lo, hi);\n            let s = _mm_add_sd(s, _mm_unpackhi_pd(s, s));\n            let mut sum = _mm_cvtsd_f64(s);\n            for kk in (chunks * 4)..k {\n                sum += ai[kk] * bj[kk];\n            }\n            out[i * n + j] = sum;\n        }\n    }\n}\n\n/// Register-tiled matmul: 4×4 micro-kernel. The 4×4 block of C lives in 4 ymm\n/// accumulators; the k-loop loads one B row (contiguous, 4 doubles) and fma's it\n/// into all 4 C rows (B reuse), broadcasting one A element per row. This is BLAS's\n/// register-blocking core — C stays in registers across k, memory traffic is just\n/// A column + B row. Ragged edges (m%4, n%4) fall back to scalar.\n#[cfg(target_arch = \"x86_64\")]\n#[target_feature(enable = \"avx2,fma\")]\nunsafe fn matmul_register_tiled(a: &[f64], m: usize, k: usize, b: &[f64], n: usize, out: &mut [f64]) {\n    use std::arch::x86_64::*;\n    let mt = m / 4 * 4;\n    let nt = n / 4 * 4;\n    for i0 in (0..mt).step_by(4) {\n        for j0 in (0..nt).step_by(4) {\n            let mut c0 = _mm256_setzero_pd();\n            let mut c1 = _mm256_setzero_pd();\n            let mut c2 = _mm256_setzero_pd();\n            let mut c3 = _mm256_setzero_pd();\n            for kk in 0..k {\n                let brow = _mm256_loadu_pd(b.as_ptr().add(kk * n + j0));\n                c0 = _mm256_fmadd_pd(_mm256_set1_pd(*a.get_unchecked((i0) * k + kk)), brow, c0);\n                c1 = _mm256_fmadd_pd(_mm256_set1_pd(*a.get_unchecked((i0 + 1) * k + kk)), brow, c1);\n                c2 = _mm256_fmadd_pd(_mm256_set1_pd(*a.get_unchecked((i0 + 2) * k + kk)), brow, c2);\n                c3 = _mm256_fmadd_pd(_mm256_set1_pd(*a.get_unchecked((i0 + 3) * k + kk)), brow, c3);\n            }\n            _mm256_storeu_pd(out.as_mut_ptr().add((i0) * n + j0), c0);\n            _mm256_storeu_pd(out.as_mut_ptr().add((i0 + 1) * n + j0), c1);\n            _mm256_storeu_pd(out.as_mut_ptr().add((i0 + 2) * n + j0), c2);\n            _mm256_storeu_pd(out.as_mut_ptr().add((i0 + 3) * n + j0), c3);\n        }\n    }\n    scalar_edges(a, b, out, Dims { m, k, n }, mt, nt);\n}\n\n/// The (i, j) cells the 4×4 tiling did not cover: the bottom `m % 4` rows in\n/// full, plus the right `n % 4` columns of every tiled row. Plain scalar dots —\n/// no intrinsics, so this half of the kernel is safe code.\n#[cfg(target_arch = \"x86_64\")]\nfn scalar_edges(a: &[f64], b: &[f64], out: &mut [f64], d: Dims, mt: usize, nt: usize) {\n    for i in 0..d.m {\n        let first_col = if i < mt { nt } else { 0 };\n        for j in first_col..d.n {\n            let mut s = 0.0;\n            for kk in 0..d.k {\n                s += a[i * d.k + kk] * b[kk * d.n + j];\n            }\n            out[i * d.n + j] = s;\n        }\n    }\n}\n\n/// Per-target dispatch.\npub fn matmul(a: &[f64], m: usize, k: usize, b: &[f64], n: usize, out: &mut [f64]) {\n    #[cfg(target_arch = \"x86_64\")]\n    {\n        if is_x86_feature_detected!(\"avx2\") && is_x86_feature_detected!(\"fma\") {\n            return unsafe { matmul_register_tiled(a, m, k, b, n, out) };\n        }\n    }\n    matmul_naive(a, m, k, b, n, out);\n}\n\n\n}\npub mod scale {\n//! Elementwise scale: `out[i] = a * x[i]`.\n//!\n//! Honest note (measured): elementwise is memory-bound. With `-C\n//! target-cpu=native` the autovectorized naive loop ties explicit AVX (0.99x) —\n//! rustc emits the same AVX. Default builds show explicit AVX ~1.23x *only*\n//! because autovec is capped at the SSE2 baseline target; the right fix is\n//! target-cpu, not shipping ceremony. So `scale` stays naive — almide-kernel's\n//! edge is *data-movement* (transpose: 4.23x native, autovec can't build a\n//! shuffle network), not elementwise. `scale_avx` exists only for the\n//! differential test + bench. Don't ship ceremony that doesn't pay — the same\n//! honesty that kept @stream out of Wyve's examples.\n\n/// Production: `out[i] = a * x[i]`. rustc autovectorizes this loop.\npub fn scale(a: f32, x: &[f32], out: &mut [f32]) {\n    assert_eq!(x.len(), out.len());\n    // iterator form: no bounds checks, rustc autovectorizes fully\n    for (o, &xi) in out.iter_mut().zip(x) {\n        *o = a * xi;\n    }\n}\n\n/// Explicit AVX — measurement only, differential-tested bitwise-equal to `scale`.\n#[cfg(target_arch = \"x86_64\")]\n#[target_feature(enable = \"avx\")]\npub unsafe fn scale_avx(a: f32, x: &[f32], out: &mut [f32]) {\n    use std::arch::x86_64::*;\n    let n = x.len();\n    let va = _mm256_set1_ps(a);\n    let chunks = n / 8;\n    for c in 0..chunks {\n        let off = c * 8;\n        let vx = _mm256_loadu_ps(x.as_ptr().add(off));\n        _mm256_storeu_ps(out.as_mut_ptr().add(off), _mm256_mul_ps(va, vx));\n    }\n    for i in (chunks * 8)..n {\n        out[i] = a * x[i];\n    }\n}\n\n\n}\npub mod transpose {\n//! 8x8 f32 transpose — Exo-style: algorithm (what) and schedule (how) separated.\n//!\n//! - `transpose_8x8_naive` is the **algorithm**: the spec, `out[j][i] = in[i][j]`.\n//! - The **schedule** is an explicit composition of named passes (load → unpack\n//!   → shuffle → permute → store), not one hand-written SIMD blob. Each pass is\n//!   an independent transform; composing them *is* the schedule. To change how\n//!   the transpose runs, recompose the passes — the algorithm above is untouched.\n//! - **Equivalence** (Exo's program-equivalence guarantee) is pinned by the\n//!   differential test: every schedule must be bitwise-exact to the naive\n//!   algorithm. Static proof (Lean) is the optional stronger backstop; the\n//!   differential test is the everyday guarantee.\n\n/// Algorithm: `out[j*8 + i] = in[i*8 + j]` (the spec every schedule must match).\npub fn transpose_8x8_naive(input: &[f32; 64]) -> [f32; 64] {\n    let mut out = [0.0f32; 64];\n    for i in 0..8 {\n        for j in 0..8 {\n            out[j * 8 + i] = input[i * 8 + j];\n        }\n    }\n    out\n}\n\n/// Public entry. Per-target schedule (AVX on x86, simd128 on wasm), naive else.\npub fn transpose_8x8(input: &[f32; 64]) -> [f32; 64] {\n    #[cfg(target_arch = \"x86_64\")]\n    {\n        if is_x86_feature_detected!(\"avx\") {\n            // SAFETY: guarded by the runtime feature check.\n            return unsafe { transpose_8x8_avx(input) };\n        }\n    }\n    #[cfg(all(target_arch = \"wasm32\", target_feature = \"simd128\"))]\n    {\n        return transpose_8x8_simd128(input);\n    }\n    #[allow(unreachable_code)]\n    transpose_8x8_naive(input)\n}\n\n// ============== schedule: wasm simd128 (128-bit = f32x4) ==============\n// 8x8 decomposes into four 4x4 blocks; each block transposed by a 4x4 shuffle\n// pass, then the off-diagonal blocks swap places. The 4x4 pass is the unit;\n// the schedule composes four of them + the block swap. Bitwise-exact (no reassoc\n// — it's pure data movement).\n\n/// pass: transpose a 4x4 block held in four f32x4 rows.\n#[cfg(all(target_arch = \"wasm32\", target_feature = \"simd128\"))]\n#[inline(always)]\nfn transpose_4x4(\n    r0: std::arch::wasm32::v128,\n    r1: std::arch::wasm32::v128,\n    r2: std::arch::wasm32::v128,\n    r3: std::arch::wasm32::v128,\n) -> [std::arch::wasm32::v128; 4] {\n    use std::arch::wasm32::*;\n    let t0 = i32x4_shuffle::<0, 4, 1, 5>(r0, r1);\n    let t1 = i32x4_shuffle::<2, 6, 3, 7>(r0, r1);\n    let t2 = i32x4_shuffle::<0, 4, 1, 5>(r2, r3);\n    let t3 = i32x4_shuffle::<2, 6, 3, 7>(r2, r3);\n    [\n        i32x4_shuffle::<0, 1, 4, 5>(t0, t2),\n        i32x4_shuffle::<2, 3, 6, 7>(t0, t2),\n        i32x4_shuffle::<0, 1, 4, 5>(t1, t3),\n        i32x4_shuffle::<2, 3, 6, 7>(t1, t3),\n    ]\n}\n\n#[cfg(all(target_arch = \"wasm32\", target_feature = \"simd128\"))]\nfn transpose_8x8_simd128(input: &[f32; 64]) -> [f32; 64] {\n    use super::simd_wasm::{load_f32x4, store_f32x4};\n    // 64 f32 = exactly 16 four-lane windows: window `2r` is row `r`'s left half\n    // (cols 0-3) and window `2r + 1` its right half (cols 4-7).\n    let (w, _) = input.as_chunks::<4>();\n    let ld = |half: usize| load_f32x4(&w[half]);\n    let (l0, r0) = (ld(0), ld(1));\n    let (l1, r1) = (ld(2), ld(3));\n    let (l2, r2) = (ld(4), ld(5));\n    let (l3, r3) = (ld(6), ld(7));\n    let (l4, r4) = (ld(8), ld(9));\n    let (l5, r5) = (ld(10), ld(11));\n    let (l6, r6) = (ld(12), ld(13));\n    let (l7, r7) = (ld(14), ld(15));\n    let a = transpose_4x4(l0, l1, l2, l3); // top-left  → out rows 0-3, left\n    let b = transpose_4x4(l4, l5, l6, l7); // bot-left  → out rows 0-3, right\n    let c = transpose_4x4(r0, r1, r2, r3); // top-right → out rows 4-7, left\n    let d = transpose_4x4(r4, r5, r6, r7); // bot-right → out rows 4-7, right\n    let mut out = [0.0f32; 64];\n    let (ow, _) = out.as_chunks_mut::<4>();\n    for j in 0..4 {\n        store_f32x4(&mut ow[j * 2], a[j]);\n        store_f32x4(&mut ow[j * 2 + 1], b[j]);\n        store_f32x4(&mut ow[(j + 4) * 2], c[j]);\n        store_f32x4(&mut ow[(j + 4) * 2 + 1], d[j]);\n    }\n    out\n}\n\n// ===================== schedule: AVX 3-pass shuffle network =====================\n// The \"how\", separated from the algorithm. Each pass is a named, independent\n// transform on the 8 row-vectors. The schedule is their composition.\n\n#[cfg(target_arch = \"x86_64\")]\nmod avx {\n    use std::arch::x86_64::*;\n\n    #[inline(always)]\n    pub unsafe fn load_rows(input: &[f32; 64]) -> [__m256; 8] {\n        let p = input.as_ptr();\n        [\n            _mm256_loadu_ps(p),\n            _mm256_loadu_ps(p.add(8)),\n            _mm256_loadu_ps(p.add(16)),\n            _mm256_loadu_ps(p.add(24)),\n            _mm256_loadu_ps(p.add(32)),\n            _mm256_loadu_ps(p.add(40)),\n            _mm256_loadu_ps(p.add(48)),\n            _mm256_loadu_ps(p.add(56)),\n        ]\n    }\n\n    /// pass 1: unpack adjacent rows within each 128-bit lane.\n    #[inline(always)]\n    pub unsafe fn pass_unpack(r: [__m256; 8]) -> [__m256; 8] {\n        [\n            _mm256_unpacklo_ps(r[0], r[1]),\n            _mm256_unpackhi_ps(r[0], r[1]),\n            _mm256_unpacklo_ps(r[2], r[3]),\n            _mm256_unpackhi_ps(r[2], r[3]),\n            _mm256_unpacklo_ps(r[4], r[5]),\n            _mm256_unpackhi_ps(r[4], r[5]),\n            _mm256_unpacklo_ps(r[6], r[7]),\n            _mm256_unpackhi_ps(r[6], r[7]),\n        ]\n    }\n\n    /// pass 2: shuffle 64-bit groups across the unpacked pairs.\n    #[inline(always)]\n    pub unsafe fn pass_shuffle(t: [__m256; 8]) -> [__m256; 8] {\n        [\n            _mm256_shuffle_ps(t[0], t[2], 0x44),\n            _mm256_shuffle_ps(t[0], t[2], 0xEE),\n            _mm256_shuffle_ps(t[1], t[3], 0x44),\n            _mm256_shuffle_ps(t[1], t[3], 0xEE),\n            _mm256_shuffle_ps(t[4], t[6], 0x44),\n            _mm256_shuffle_ps(t[4], t[6], 0xEE),\n            _mm256_shuffle_ps(t[5], t[7], 0x44),\n            _mm256_shuffle_ps(t[5], t[7], 0xEE),\n        ]\n    }\n\n    /// pass 3: permute 128-bit lanes to finish the transpose.\n    #[inline(always)]\n    pub unsafe fn pass_permute(s: [__m256; 8]) -> [__m256; 8] {\n        [\n            _mm256_permute2f128_ps(s[0], s[4], 0x20),\n            _mm256_permute2f128_ps(s[1], s[5], 0x20),\n            _mm256_permute2f128_ps(s[2], s[6], 0x20),\n            _mm256_permute2f128_ps(s[3], s[7], 0x20),\n            _mm256_permute2f128_ps(s[0], s[4], 0x31),\n            _mm256_permute2f128_ps(s[1], s[5], 0x31),\n            _mm256_permute2f128_ps(s[2], s[6], 0x31),\n            _mm256_permute2f128_ps(s[3], s[7], 0x31),\n        ]\n    }\n\n    #[inline(always)]\n    pub unsafe fn store_rows(rows: [__m256; 8]) -> [f32; 64] {\n        let mut out = [0.0f32; 64];\n        let q = out.as_mut_ptr();\n        _mm256_storeu_ps(q, rows[0]);\n        _mm256_storeu_ps(q.add(8), rows[1]);\n        _mm256_storeu_ps(q.add(16), rows[2]);\n        _mm256_storeu_ps(q.add(24), rows[3]);\n        _mm256_storeu_ps(q.add(32), rows[4]);\n        _mm256_storeu_ps(q.add(40), rows[5]);\n        _mm256_storeu_ps(q.add(48), rows[6]);\n        _mm256_storeu_ps(q.add(56), rows[7]);\n        out\n    }\n}\n\n/// The AVX schedule: load → unpack → shuffle → permute → store, composed.\n/// This single line *is* the schedule — recompose the passes to change it.\n#[cfg(target_arch = \"x86_64\")]\n#[target_feature(enable = \"avx\")]\nunsafe fn transpose_8x8_avx(input: &[f32; 64]) -> [f32; 64] {\n    use avx::*;\n    store_rows(pass_permute(pass_shuffle(pass_unpack(load_rows(input)))))\n}\n\n/// Transpose an arbitrary `rows × cols` row-major f32 matrix into `out`\n/// (`cols × rows`). This is what `almide_rt` actually needs — Almide's matrices\n/// aren't 8x8. Full 8x8 tiles go through the SIMD kernel; the ragged right/bottom\n/// edges are scalar. Bitwise-exact (data movement, no reassoc).\npub fn transpose_matrix(input: &[f32], rows: usize, cols: usize, out: &mut [f32]) {\n    assert_eq!(input.len(), rows * cols);\n    assert_eq!(out.len(), rows * cols);\n    let rt = rows / 8 * 8; // tiled extent (multiple of 8)\n    let ct = cols / 8 * 8;\n    for ti in (0..rt).step_by(8) {\n        for tj in (0..ct).step_by(8) {\n            transpose_tile(input, rows, cols, out, ti, tj);\n        }\n    }\n    transpose_edges(input, rows, cols, out, rt, ct);\n}\n\n/// Gather the 8x8 tile whose top-left corner is `(ti, tj)`, run it through the\n/// SIMD kernel, and scatter the result into its transposed position.\nfn transpose_tile(input: &[f32], rows: usize, cols: usize, out: &mut [f32], ti: usize, tj: usize) {\n    let mut tile = [0.0f32; 64];\n    for r in 0..8 {\n        let base = (ti + r) * cols + tj;\n        tile[r * 8..r * 8 + 8].copy_from_slice(&input[base..base + 8]);\n    }\n    let t = transpose_8x8(&tile);\n    for r in 0..8 {\n        let base = (tj + r) * rows + ti;\n        out[base..base + 8].copy_from_slice(&t[r * 8..r * 8 + 8]);\n    }\n}\n\n/// The (i, j) cells no full 8x8 tile covered: the bottom `rows % 8` rows in\n/// full, plus the right `cols % 8` columns of every tiled row.\nfn transpose_edges(input: &[f32], rows: usize, cols: usize, out: &mut [f32], rt: usize, ct: usize) {\n    for i in 0..rows {\n        let first_col = if i < rt { ct } else { 0 };\n        for j in first_col..cols {\n            out[j * rows + i] = input[i * cols + j];\n        }\n    }\n}\n\n\n}\npub mod transpose_f64 {\n//! f64 transpose — Almide's matrices are f64, and transpose is data movement, so\n//! an f64 kernel keeps the values exact (no f32 rounding). AVX uses f64x4\n//! (256-bit), so 8x8 decomposes into four 4x4 blocks (same shape as the wasm\n//! f32 path). Bitwise-exact.\n\n/// Algorithm: `out[j*8+i] = in[i*8+j]` in f64.\npub fn transpose_8x8_f64_naive(input: &[f64; 64]) -> [f64; 64] {\n    let mut out = [0.0f64; 64];\n    for i in 0..8 {\n        for j in 0..8 {\n            out[j * 8 + i] = input[i * 8 + j];\n        }\n    }\n    out\n}\n\n/// Public entry: AVX f64x4 when available, naive otherwise.\npub fn transpose_8x8_f64(input: &[f64; 64]) -> [f64; 64] {\n    #[cfg(target_arch = \"x86_64\")]\n    {\n        if is_x86_feature_detected!(\"avx\") {\n            // SAFETY: guarded by the runtime feature check.\n            return unsafe { transpose_8x8_f64_avx(input) };\n        }\n    }\n    transpose_8x8_f64_naive(input)\n}\n\n#[cfg(target_arch = \"x86_64\")]\n#[inline(always)]\nunsafe fn transpose_4x4_f64(\n    r0: std::arch::x86_64::__m256d,\n    r1: std::arch::x86_64::__m256d,\n    r2: std::arch::x86_64::__m256d,\n    r3: std::arch::x86_64::__m256d,\n) -> [std::arch::x86_64::__m256d; 4] {\n    use std::arch::x86_64::*;\n    let t0 = _mm256_unpacklo_pd(r0, r1);\n    let t1 = _mm256_unpackhi_pd(r0, r1);\n    let t2 = _mm256_unpacklo_pd(r2, r3);\n    let t3 = _mm256_unpackhi_pd(r2, r3);\n    [\n        _mm256_permute2f128_pd(t0, t2, 0x20),\n        _mm256_permute2f128_pd(t1, t3, 0x20),\n        _mm256_permute2f128_pd(t0, t2, 0x31),\n        _mm256_permute2f128_pd(t1, t3, 0x31),\n    ]\n}\n\n#[cfg(target_arch = \"x86_64\")]\n#[target_feature(enable = \"avx\")]\nunsafe fn transpose_8x8_f64_avx(input: &[f64; 64]) -> [f64; 64] {\n    use std::arch::x86_64::*;\n    let p = input.as_ptr();\n    let ld = |off: usize| _mm256_loadu_pd(p.add(off));\n    // each row = left (cols 0-3) + right (cols 4-7)\n    let (l0, r0) = (ld(0), ld(4));\n    let (l1, r1) = (ld(8), ld(12));\n    let (l2, r2) = (ld(16), ld(20));\n    let (l3, r3) = (ld(24), ld(28));\n    let (l4, r4) = (ld(32), ld(36));\n    let (l5, r5) = (ld(40), ld(44));\n    let (l6, r6) = (ld(48), ld(52));\n    let (l7, r7) = (ld(56), ld(60));\n    let a = transpose_4x4_f64(l0, l1, l2, l3); // top-left  → rows 0-3, left\n    let b = transpose_4x4_f64(l4, l5, l6, l7); // bot-left  → rows 0-3, right\n    let c = transpose_4x4_f64(r0, r1, r2, r3); // top-right → rows 4-7, left\n    let d = transpose_4x4_f64(r4, r5, r6, r7); // bot-right → rows 4-7, right\n    let mut out = [0.0f64; 64];\n    let q = out.as_mut_ptr();\n    for j in 0..4 {\n        _mm256_storeu_pd(q.add(j * 8), a[j]);\n        _mm256_storeu_pd(q.add(j * 8 + 4), b[j]);\n        _mm256_storeu_pd(q.add((j + 4) * 8), c[j]);\n        _mm256_storeu_pd(q.add((j + 4) * 8 + 4), d[j]);\n    }\n    out\n}\n\n/// Arbitrary-size f64 transpose: 8x8 tiles through the SIMD kernel, scalar edges.\npub fn transpose_matrix_f64(input: &[f64], rows: usize, cols: usize, out: &mut [f64]) {\n    assert_eq!(input.len(), rows * cols);\n    assert_eq!(out.len(), rows * cols);\n    let rt = rows / 8 * 8; // tiled extent (multiple of 8)\n    let ct = cols / 8 * 8;\n    for ti in (0..rt).step_by(8) {\n        for tj in (0..ct).step_by(8) {\n            transpose_tile_f64(input, rows, cols, out, ti, tj);\n        }\n    }\n    transpose_edges_f64(input, rows, cols, out, rt, ct);\n}\n\n/// Gather the 8x8 tile whose top-left corner is `(ti, tj)`, run it through the\n/// SIMD kernel, and scatter the result into its transposed position.\nfn transpose_tile_f64(input: &[f64], rows: usize, cols: usize, out: &mut [f64], ti: usize, tj: usize) {\n    let mut tile = [0.0f64; 64];\n    for r in 0..8 {\n        let base = (ti + r) * cols + tj;\n        tile[r * 8..r * 8 + 8].copy_from_slice(&input[base..base + 8]);\n    }\n    let t = transpose_8x8_f64(&tile);\n    for r in 0..8 {\n        let base = (tj + r) * rows + ti;\n        out[base..base + 8].copy_from_slice(&t[r * 8..r * 8 + 8]);\n    }\n}\n\n/// The (i, j) cells no full 8x8 tile covered: the bottom `rows % 8` rows in\n/// full, plus the right `cols % 8` columns of every tiled row.\nfn transpose_edges_f64(input: &[f64], rows: usize, cols: usize, out: &mut [f64], rt: usize, ct: usize) {\n    for i in 0..rows {\n        let first_col = if i < rt { ct } else { 0 };\n        for j in first_col..cols {\n            out[j * rows + i] = input[i * cols + j];\n        }\n    }\n}\n\n\n}\n}\n";
